func (q *Queries) UpdateExternalPlannerItemNativeState(ctx context.Context, arg UpdateExternalPlannerItemNativeStateParams) (PlannerItem, error) {
	row := q.db.QueryRowContext(ctx, updateExternalPlannerItemNativeState,
		arg.Title,
		arg.Details,
		arg.DueAt,
		arg.DueDate,
		arg.Status,
		arg.CompletedAt,
		arg.UpdatedAt,
		arg.LastRevisionID,
		arg.EntityID,
	)
	var i PlannerItem
	err := row.Scan(
		&i.EntityID,
		&i.AuthorityType,
		&i.WorkItemID,
		&i.WorkflowID,
		&i.WorkflowStepID,
		&i.RelatedEntityID,
		&i.MonitorPointID,
		&i.ItemType,
		&i.Title,
		&i.Details,
		&i.Status,
		&i.ScheduledAt,
		&i.DueAt,
		&i.ScheduledDate,
		&i.DueDate,
		&i.ContextStatus,
		&i.MissingContextJson,
		&i.LastRevisionID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CompletedAt,
		&i.LocalNote,
	)
	return i, err
}

const updatePlannerItemLocalNote = `-- name: UpdatePlannerItemLocalNote :one
UPDATE planner_items
SET
    local_note = ?1,
    updated_at = ?2,
    last_revision_id = ?3
WHERE entity_id = ?4
RETURNING
    entity_id,
    authority_type,
    work_item_id,
    workflow_id,
    workflow_step_id,
    related_entity_id,
    monitor_point_id,
    item_type,
    title,
    details,
    status,
    scheduled_at,
    due_at,
    scheduled_date,
    due_date,
    context_status,
    missing_context_json,
    last_revision_id,
    created_at,
    updated_at,
    completed_at,
    local_note
`

type UpdatePlannerItemLocalNoteParams struct {
	LocalNote      *string
	UpdatedAt      string
	LastRevisionID string
	EntityID       string
}

// Replaces only the Lum Harbor-owned local_note of one Planner Item. No
// external-authoritative column (title/details/due/status/completed_at) is
// referenced; authority and stale checks belong to PlannerService.
func (q *Queries) UpdatePlannerItemLocalNote(ctx context.Context, arg UpdatePlannerItemLocalNoteParams) (PlannerItem, error) {
	row := q.db.QueryRowContext(ctx, updatePlannerItemLocalNote,
		arg.LocalNote,
		arg.UpdatedAt,
		arg.LastRevisionID,
		arg.EntityID,
	)
	var i PlannerItem
	err := row.Scan(
		&i.EntityID,
		&i.AuthorityType,
		&i.WorkItemID,
		&i.WorkflowID,
		&i.WorkflowStepID,
		&i.RelatedEntityID,
		&i.MonitorPointID,
		&i.ItemType,
		&i.Title,
		&i.Details,
		&i.Status,
		&i.ScheduledAt,
		&i.DueAt,
		&i.ScheduledDate,
		&i.DueDate,
		&i.ContextStatus,
		&i.MissingContextJson,
		&i.LastRevisionID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CompletedAt,
		&i.LocalNote,
	)
	return i, err
}
